with unpacked as (select id, customer_id, created_at, ship_to, attributes, coalesce(attributes['device'], 'unknown') as device_or_default, array_join(array_sort(coupon_codes), ',') as coupons_text, ship_to.city as ship_city from carts) select ship_city, date_trunc('hour', created_at) as hour_window, min(created_at) as started_at, count(case when ship_city = 'London' then 1 end) as london_count, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as span_minutes from unpacked group by ship_city, date_trunc('hour', created_at) having count(case when ship_city = 'London' then 1 end) > 1;
